template <typename T>
__device__ static __forceinline__ T DupExprCombine0(T p0, T p1) {
  return (p0 + p1);
}

// DupExpr: launch 64 CTAs x 32 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
